/**
 * Extract and validate Ghost webhook payload.
 * 
 * Ghost sends: { post: { current: { id, slug, title, url, status, ... } } }
 */
const post = $input.first().json.post?.current;

if (!post || !post.id) {
  throw new Error('Ghost webhook payload missing post.current.id');
}

// Only process published posts
if (post.status !== 'published') {
  return [{ json: { skip: true, reason: `Post status is '${post.status}', not 'published'` } }];
}

// Derive site info from post URL
const postUrl = new URL(post.url);
const siteBase = postUrl.origin;
const siteSlug = postUrl.hostname.split('.')[0];

// Build unique job ID
const jobId = `${siteSlug}-${post.slug}`;

return [{
  json: {
    skip: false,
    postId: post.id,
    postSlug: post.slug,
    postTitle: post.title,
    postUrl: post.url,
    siteBase,
    siteSlug,
    jobId,
    timestamp: new Date().toISOString(),
  }
}];

const data = $input.first().json;
console.log(`⏭ Skipped: ${data.reason}`);
return [{ json: { skipped: true, reason: data.reason } }];

const healthResponse = $input.first().json;
const origData = $('Extract Post Metadata').first().json;

console.error(`✗ TTS service not ready for "${origData.postTitle}": ${healthResponse.reason || 'Unknown reason'}`);

throw new Error(`TTS service not ready: ${healthResponse.reason || 'Service unavailable'}`);

/**
 * Clean article text before LLM processing.
 */
const post = $input.first().json.posts?.[0];
const prevData = $('Extract Post Metadata').first().json;

if (!post) {
  throw new Error('Ghost Content API returned no posts');
}

let text = post.plaintext || '';

// Remove bare URLs
text = text.replace(/^https?:\/\/\S+$/gm, '');

// Remove markdown headers
text = text.replace(/^#{1,6}\s+/gm, '');

// Decode HTML entities
text = text
  .replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/&nbsp;/g, ' ')
  .replace(/&quot;/g, '"')
  .replace(/&#39;/g, "'");

// Collapse excessive blank lines
text = text.replace(/\n{3,}/g, '\n\n').trim();

const wordCount = text.split(/\s+/).filter(w => w.length > 0).length;

if (!text || wordCount < 50) {
  throw new Error(`Article text too short (${wordCount} words) for post '${post.slug}'`);
}

return [{
  json: {
    ...prevData,
    rawText: text,
    wordCount,
    readingTime: post.reading_time || Math.ceil(wordCount / 200),
    publishedAt: post.published_at,
    featureImage: post.feature_image,
  }
}];

