/**
 * Extract narration text from LLM response.
 */
const llmResponse = $input.first().json;
const prevData = $('Clean & Prepare Article Text').first().json;

const narrationText = llmResponse?.choices?.[0]?.message?.content?.trim();

if (!narrationText) {
  throw new Error('LLM returned empty narration text');
}

// Clean residual markdown
const cleaned = narrationText
  .replace(/\*{1,3}(.*?)\*{1,3}/g, '$1')
  .replace(/^#{1,6}\s+/gm, '')
  .replace(/\[([^\]]+)\]\([^)]+\)/g, '$1')
  .replace(/<[^>]+>/g, '')
  .trim();

const narrationWordCount = cleaned.split(/\s+/).filter(w => w.length > 0).length;
const estimatedDurationMinutes = Math.ceil(narrationWordCount / 150);

return [{
  json: {
    ...prevData,
    narrationText: cleaned,
    narrationWordCount,
    estimatedDurationMinutes,
  }
}];

