/**
 * Store all context needed for polling and final result.
 * This data persists through the retry loop.
 */
const ttsResponse = $input.first().json;
const articleData = $('Parse Narration Text').first().json;

return [{
  json: {
    // Essential polling data
    jobId: ttsResponse.job_id,

    // Article metadata for final result
    postTitle: articleData.postTitle,
    postSlug: articleData.postSlug,
    postUrl: articleData.postUrl,
    siteSlug: articleData.siteSlug,
    wordCount: articleData.wordCount,
    narrationWordCount: articleData.narrationWordCount,
    estimatedDurationMinutes: articleData.estimatedDurationMinutes,

    // Tracking
    submittedAt: new Date().toISOString(),
    retryCount: 0,
    maxRetries: 30,
  }
}];

/**
 * Evaluate TTS status and prepare routing decision.
 * 
 * Context Strategy:
 * - Always get base context from 'Prepare Polling Context' (runs once at start)
 * - Track retries using workflow execution start time vs current time
 * - This avoids n8n's limitation with referencing loop iteration data
 */
const statusResponse = $input.first().json;

// Get original context from Prepare Polling Context (always available)
const context = $('Prepare Polling Context').first().json;

if (!context || !context.jobId) {
  throw new Error('Lost polling context - cannot continue');
}

// Calculate retry count based on elapsed time
// Initial wait: 2 min, Retry wait: 45 sec
const submittedAt = new Date(context.submittedAt).getTime();
const elapsedMs = Date.now() - submittedAt;
const initialWaitMs = 2 * 60 * 1000; // 2 minutes
const retryWaitMs = 45 * 1000; // 45 seconds

let estimatedRetryCount = 1;
if (elapsedMs > initialWaitMs) {
  estimatedRetryCount = 1 + Math.floor((elapsedMs - initialWaitMs) / retryWaitMs);
}

const maxRetries = context.maxRetries || 30;

// Determine routing based on status
let route = 'retry';
if (statusResponse.status === 'completed') {
  route = 'completed';
} else if (statusResponse.status === 'failed') {
  route = 'failed';
} else if (estimatedRetryCount >= maxRetries) {
  route = 'timeout';
}

return [{
  json: {
    // Routing decision
    route,

    // Context data (from original submission)
    jobId: context.jobId,
    postTitle: context.postTitle,
    postSlug: context.postSlug,
    postUrl: context.postUrl,
    siteSlug: context.siteSlug,
    wordCount: context.wordCount,
    narrationWordCount: context.narrationWordCount,
    estimatedDurationMinutes: context.estimatedDurationMinutes,
    submittedAt: context.submittedAt,
    maxRetries: maxRetries,
    retryCount: estimatedRetryCount,
    elapsedSeconds: Math.round(elapsedMs / 1000),

    // Status response from TTS service
    status: statusResponse.status,
    job_id: statusResponse.job_id,
    gcs_uri: statusResponse.gcs_uri,
    local_path: statusResponse.local_path,
    error: statusResponse.error,
    duration_seconds: statusResponse.duration_seconds,
    completed_at: statusResponse.completed_at,
  }
}];

/**
 * Job completed successfully!
 */
const data = $input.first().json;

const result = {
  success: true,
  message: 'Audio generation complete',
  postTitle: data.postTitle,
  postSlug: data.postSlug,
  postUrl: data.postUrl,
  siteSlug: data.siteSlug,
  gcsUri: data.gcs_uri,
  localPath: data.local_path,
  jobId: data.jobId,
  submittedAt: data.submittedAt,
  completedAt: data.completed_at ? new Date(data.completed_at * 1000).toISOString() : new Date().toISOString(),
  processingDurationSeconds: data.duration_seconds,
  originalWordCount: data.wordCount,
  narrationWordCount: data.narrationWordCount,
  estimatedAudioMinutes: data.estimatedDurationMinutes,
  pollRetries: data.retryCount,
};

console.log(`✓ Audio ready for "${data.postTitle}"`);
console.log(`  GCS URI: ${data.gcs_uri}`);
console.log(`  Processing: ${data.duration_seconds?.toFixed(1)}s`);
console.log(`  Poll retries: ${data.retryCount}`);

return [{ json: result }];

/**
 * TTS job failed.
 */
const data = $input.first().json;

const result = {
  success: false,
  message: 'TTS job failed',
  postTitle: data.postTitle,
  postSlug: data.postSlug,
  postUrl: data.postUrl,
  siteSlug: data.siteSlug,
  jobId: data.jobId,
  error: data.error || 'Unknown error',
  submittedAt: data.submittedAt,
  failedAt: new Date().toISOString(),
  retryCount: data.retryCount,
};

console.error(`✗ TTS failed for "${data.postTitle}": ${data.error}`);
console.error(`  Job ID: ${data.jobId}`);

return [{ json: result }];

/**
 * Job exceeded maximum retry attempts.
 */
const data = $input.first().json;

const result = {
  success: false,
  message: 'TTS job timed out (max retries exceeded)',
  postTitle: data.postTitle,
  postSlug: data.postSlug,
  postUrl: data.postUrl,
  siteSlug: data.siteSlug,
  jobId: data.jobId,
  lastStatus: data.status,
  retryCount: data.retryCount,
  maxRetries: data.maxRetries,
  submittedAt: data.submittedAt,
  timedOutAt: new Date().toISOString(),
};

console.error(`✗ TTS timed out for "${data.postTitle}" after ${data.retryCount} retries`);
console.error(`  Job ID: ${data.jobId}`);
console.error(`  Last status: ${data.status}`);

return [{ json: result }];
